INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b8cf5df7-c0a4-43ad-b4f3-6e93e7a839a2', '150f78d3-019b-40c0-962e-a83576309ea5', 4, 'O Coração que Escuta', NULL, '{"intro": "Escutar \u00e9 a forma mais profunda de amar.", "prayer": "Escute o sil\u00eancio de Deus no seu peito.", "practice": "Escute algu\u00e9m hoje sem interromper, sem julgar.", "reflection": "O amor tem ouvidos que a raz\u00e3o desconhece.", "journal_prompt": "Voc\u00ea est\u00e1 realmente ouvindo ou apenas esperando sua vez de falar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;